using System.Text;
using System.Text.Json;
using static SafeJunkCleaner.QuickClean.Store;
namespace SafeJunkCleaner.QuickClean;

internal sealed partial class Jobs {
    public object Query(string op,JsonElement j){if(op=="History"){j.Fields();return History();}
        Require(op is "Preview" or "Page" or "RuleKeep" or "Export","UnknownQuery");var allowed=new[]{"taskId","offset","limit","ruleId","excludedIds","destination"};Require(j.EnumerateObject().All(p=>allowed.Contains(p.Name)),"UnknownQueryField");string t=TaskPath(j.Str("taskId"));var(f,m)=Plan(t);using(f)using(var reader=new StreamReader(f,new UTF8Encoding(false,true))){int offset=j.TryGetProperty("offset",out var o)?o.GetInt32():0,limit=j.TryGetProperty("limit",out var l)?l.GetInt32():200;Require(offset>=0&&limit is >0 and <=1000,"InvalidPage");string? rule=op=="RuleKeep"?j.Str("ruleId"):null;var keep=op=="Export"?Strings(j,"excludedIds",1000000).ToHashSet():[];string? dest=null,tmp=null;StreamWriter? wr=null;
            try{if(op=="Export"){dest=Canon(j.Str("destination"));Require(dest.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)&&!Within(dest,state)&&!File.Exists(dest)&&!Directory.Exists(dest),"InvalidExportDestination");var parent=Path.GetDirectoryName(dest)!;Plain(parent);tmp=Path.Combine(parent,".sjc-export-"+Guid.NewGuid().ToString("N"));wr=new StreamWriter(new FileStream(tmp,FileMode.CreateNew,FileAccess.Write,FileShare.None),new UTF8Encoding(true));wr.WriteLine("CandidateId,RuleId,CandidatePath,CandidateLengthBytes,LastWriteUtc");}
                var page=new List<Row>();long count=0,exported=0;bool more=false;while(reader.ReadLine() is {} line){var r=JsonSerializer.Deserialize<Row>(line)!;if(rule!=null&&r.RuleId!=rule)continue;if(wr!=null){if(!keep.Remove(r.Id)){wr.WriteLine(string.Join(',',new[]{r.Id,r.RuleId,r.Path,r.Length.ToString(),r.LastWriteUtc}.Select(x=>"\""+x.Replace("\"","\"\"")+"\"")));exported++;}}else if(count>=offset){if(page.Count==limit){more=true;break;}page.Add(r);}count++;}
                if(wr!=null){Require(keep.Count==0&&count==m.Count,"ExportCountMismatch");wr.Dispose();File.Move(tmp!,dest!);return new{ExportedCount=exported,Destination=dest,Status="Success"};}return new{Count=m.Count,Items=page,HasMore=more};
            }finally{wr?.Dispose();}}}
    object History(){var rows=new List<object>();string tasks=Path.Combine(state,"Tasks");if(!Directory.Exists(tasks))return new{Items=rows};Private(tasks);foreach(string d in Directory.EnumerateDirectories(tasks))try{TaskPath(Path.GetFileName(d));foreach(var file in Directory.EnumerateFiles(d,".history-*")){var r=Open(file);if(r.Str("TaskDirectory")!=d)continue;var log=r.Str("LogPath");if(log!=""){Channel(d,log);PlainFile(log);}string status=r.Str("Status");string action=r.Str("Action");rows.Add(new{Time=r.Str("Time"),Action=action switch{"Scan"=>"扫描","Clean"=>"清理","Recycle"=>"回收站",_=>"未知"},Status=status switch{"Success"=>"完成","Partial"=>"部分完成","Cancelled"=>"已取消","Failed"=>"失败",_=>"结果未知"},Summary=r.Str("Summary"),LogPath=log,TaskDirectory=d,Result=(object?)null});}}catch(Exception e)when(e is IOException or InvalidDataException or UnauthorizedAccessException or FormatException or System.ComponentModel.Win32Exception or JsonException){continue;}return new{Items=rows.OrderByDescending(r=>JsonSerializer.SerializeToElement(r).Str("Time"),StringComparer.Ordinal)};}
}
